"""Render a self-contained static evidence report, standard library only."""
import csv
import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent

def read_json(path): return json.loads((ROOT / path).read_text())
def read_csv(path):
    with (ROOT / path).open(newline='') as stream: return list(csv.DictReader(stream))
def esc(value): return html.escape(str(value))
def table(headers, body):
    return '<div class="scroll"><table><thead><tr>' + ''.join('<th>' + esc(h) + '</th>' for h in headers) + '</tr></thead><tbody>' + ''.join('<tr>' + ''.join('<td>' + esc(cell) + '</td>' for cell in row) + '</tr>' for row in body) + '</tbody></table></div>'
def fmt(value): return f'{float(value):,.2f}'

def chart(curve):
    nav = [float(r['nav']) for r in curve]
    low, high = 0, 60000
    width, height, left, top = 880, 260, 64, 20
    plotw, ploth = 790, 210
    points = ' '.join(f'{left+i/(len(nav)-1)*plotw:.2f},{top+ploth-(v-low)/(high-low)*ploth:.2f}' for i,v in enumerate(nav))
    lines = ''.join(f'<line x1="{left}" x2="{left+plotw}" y1="{top+ploth-v/high*ploth}" y2="{top+ploth-v/high*ploth}" stroke="#dbe4ee"/><text x="54" y="{top+ploth-v/high*ploth+4}" text-anchor="end">${v//1000}k</text>' for v in (0,20000,40000,60000))
    return f'<svg viewBox="0 0 {width} {height}" role="img" aria-label="Archived selected winner NAV: June 2025 through June 2026, outside the requested four-year evaluation"><title>Archived selected interval; arithmetic check only</title>{lines}<polyline fill="none" stroke="#225bb4" stroke-width="2.5" points="{points}"/><text x="64" y="255">{esc(curve[0]["date"])}</text><text x="854" y="255" text-anchor="end">{esc(curve[-1]["date"])}</text></svg>'

def main():
    config = read_json('config.json')
    status = read_json('validation_status.json')
    winner = read_json('archived_winner_recheck.json')
    verification = read_json('verification.json')
    tests = read_json('test_results.json')
    prior = read_csv('archived_annual_diagnostics.csv')
    growth = [r for r in prior if r['candidate'] == 'growth_margin5' and r['year'] in ('2024','2025')]
    by = {}
    for r in growth: by.setdefault(r['scenario'], {})[r['year']] = r
    scenarios = ['baseline','additional_delay_1','additional_delay_5','additional_delay_20','retain_rank35_20bps','retain_rank35_100bps','preserve_weights_20bps','preserve_weights_100bps','retain_and_preserve_20bps','retain_and_preserve_100bps','storage_memory_cluster','current_technology_sector']
    rows = [[s, by[s]['2024']['rule'], by[s]['2024']['cost_bps_per_side'], fmt(by[s]['2024']['annual_return_pct'])+'%', fmt(by[s]['2025']['annual_return_pct'])+'%'] for s in scenarios]
    retention = read_csv('archived_retention_recheck.csv')
    retention_rows = [[r['policy'],r['bps'],r['overlapping_accounts'],r['at_least_80_pct'],fmt(r['median_return_pct'])+'%',fmt(r['worst_return_pct'])+'%',fmt(r['largest_account_drawdown_pct'])+'%'] for r in retention]
    documents = ['annual_comparison.csv','monthly_leadership.csv','stock_selection_audit.csv','trades.csv','daily_portfolio_nav.csv','holdings.csv','drawdown_analysis.csv','failure_attribution.md','adaptive_strategy_review.md','data_quality_audit.md','experiment_log.md','strategy_recovery.md','config.json','validation_status.json','source_manifest.json','archived_annual_diagnostics.csv','archived_retention_recheck.csv','archived_winner_recheck.json','archived_winner_nav.csv','archived_experiment_registry.json','verification.json','test_results.json','validate_archive.py','test_validation.py','build_report.py','README.md']
    parts = ['''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Point-in-time strategy validation — 11 October 2026</title><style>
body{margin:0;background:#f3f6fa;color:#192b40;font:16px/1.6 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:36px 24px}h1{font-size:36px;line-height:1.2}h2{margin-top:36px;font-size:24px}h3{font-size:19px}.banner{border-left:6px solid #b67a18;padding:20px;background:#fff4dd}.card{padding:22px;background:white;border-radius:9px;margin:20px 0}.muted{color:#53677b}.scroll{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;padding:10px;border-bottom:1px solid #dbe4ee;vertical-align:top}th{background:#e8eff6}a{color:#225bb4}svg{width:100%;height:auto;font-size:12px}code{background:#e8eff6;padding:3px 5px}.links{columns:2}.links li{margin:6px 0}@media(max-width:650px){main{padding:20px 14px}h1{font-size:28px}.links{columns:1}}</style><main>
<p class="muted">RESEARCH ONLY · 11 OCTOBER 2026 · $10,000 requested starting capital</p><h1>Point-in-time strategy validation</h1>
<div class="banner"><strong>Final classification: Insufficient data.</strong><p>The requested 2022–2025 A–F validation is blocked. No new strategy simulations were run. Approximately 80% sustainable annual returns and repeatable 5× growth are not established. The completed work is an archive-recovery, data-quality and capital-accounting audit.</p></div>
<p>The same fixed process has not been shown to identify changing leaders, retain winners, protect capital and compound effectively across all four requested years without forward-looking information. Missing certified inputs and an unrecovered original control prevent that conclusion. Positive archived results remain retrospective hypotheses.</p>''']
    parts.append('<h2>Requested accounts: every result is unavailable</h2><p>Four independent calendar-year portfolios and one continuous January 2022–December 2025 account are required for each strategy. The 30 account records below contain explicit blocked states. No zero-return cash portfolios, missing-year interpolation or annual slices from different accounts have been substituted.</p>')
    parts.append(table(['Strategy','Recovered rule status','2022 reset','2023 reset','2024 reset','2025 reset','Continuous four years'],[[s['id']+' — '+s['name'],s['rule_status'],*(['BLOCKED / N/A']*5)] for s in config['strategies']]))
    parts.append('<p>Annual returns; cumulative return and CAGR; best, median and worst rolling 12-month return; worst complete year; full and annual drawdowns; average/minimum exposure; trades, turnover and costs; stock/industry contributions; maximum concentration; SPY comparison are all unavailable for these requested accounts. See <a href="annual_comparison.csv">annual_comparison.csv</a>. Blank fields mean unavailable, never zero.</p><p>All 48 months are recorded for each strategy in <a href="monthly_leadership.csv">monthly_leadership.csv</a> (288 status rows). Rankings, signal availability dates and actual decisions remain blank. Required trades/NAV/holdings/selection files are schema-only, not completed histories.</p>')
    parts.append('<h2>Why validation is blocked</h2>')
    parts.append(table(['Gate','Finding','Source'],[[g['id'],g['reason'],g['evidence']] for g in config['gates']]))
    parts.append('<p>The original 75/25 control cannot be silently replaced by the adaptive reconstruction. Its archived reconciliation is explicitly BLOCKED: claimed original 2024 return +50.52% versus reconstructed +3.40%, and original transaction/NAV references are missing. The phase-2 broad panel begins in January 2024. Its earlier history probe covers only 12 selected live series; the separate 2022–2026 reconstruction does not supply certified original inputs.</p>')
    parts.append('<h2>Recovered historical diagnostics — outside the validation table</h2><div class="card"><h3>Growth/margin: one strong year does not establish repeatability</h3><p>The following are inherited annual slices of continuous accounts, not new January-reset simulations. Shared input limitations remain. The complete archive runs through October 2026; this table shows only its 2024 and 2025 slices.</p>')
    parts.append(table(['Archived scenario','Holding rule','Cost bps/side','2024 slice','2025 slice'],rows))
    parts.append('<p>The baseline reaches +80% in one of its two available complete slices, 2025 only. The storage/memory exclusion reduces 2025 from +95.41% to +33.90%. Current-technology exclusion yields −7.28%. Exclusions are hindsight sensitivity tests; current sectors cannot substitute for historical industries. Higher costs lower rank-retention 2025 from +81.98% to +75.26%. Delays sometimes improve archived results; no optimal delay was selected from those outcomes.</p><p>Rank retention and weight preservation are separate changes. Their combined scenario changes two variables and cannot establish either isolated effect. These experiments do not cover the full requested gap/liquidity/concentration suite.</p></div>')
    parts.append('<div class="card"><h3>Holding experiments: descriptive overlapping starts</h3><p>New aggregation of 264 archived accounts: 22 overlapping annual starts × six policies × two costs. Initial baskets are fixed, with no replacement entries. The counts below are not independent-trial success rates or estimates of future probability.</p>')
    parts.append(table(['Policy','bps/side','Overlapping starts','Starts ≥80%','Median return','Worst return','Largest account DD'],retention_rows))
    parts.append('<p>Untouched holding at 20 bps has a +33.00% median, −5.30% worst start and −34.72% largest drawdown. This descriptive median is not a sustainable return forecast. Static holding does not establish adaptive rotation.</p></div>')
    parts.append('<h2>Selected winner: accounting passes, strategy validation does not</h2><p><strong>This chart is June 2025–June 2026, outside the requested four-year evaluation.</strong> It is one selected archived interval. New accounting checks use published trade quantities, quotes and dividend events; they do not independently verify signal selection, original price authenticity or publication-time fundamentals.</p>')
    parts.append(chart(read_csv('archived_winner_nav.csv')))
    parts.append(table(['Arithmetic measure','Rechecked value'],[['Starting / ending NAV','$10,000 → $'+fmt(winner['ending_nav'])],['Return / maximum drawdown',fmt(winner['return_pct'])+'% / '+fmt(winner['max_drawdown_pct'])+'%'],['Trades / daily books',str(winner['trades'])+' / '+str(winner['sessions'])],['Transaction costs / dividends','$'+fmt(winner['cost_dollars'])+' / $'+fmt(winner['cash_dividends'])],['Maximum stock / storage-memory cluster weight',fmt(winner['maximum_position_weight_pct'])+'% / '+fmt(winner['maximum_storage_memory_cluster_weight_pct'])+'%'],['Top three share of positive PnL',fmt(winner['top3_share_positive_pnl_pct'])+'%'],['Average / minimum equity exposure',fmt(winner['average_equity_exposure_pct'])+'% / '+fmt(winner['minimum_equity_exposure_pct'])+'%']]))
    parts.append('<p>MU, WDC and STX dominate positive profit. ANET and SNDK lose money in this account. The inherited 100-bps case still exceeds +400% before terminal liquidation, so costs alone do not invalidate the selected interval. Its concentration, timing and missing PIT certification prevent using it as repeatable 5× evidence.</p>')
    parts.append('<h2>Selection, holding and capital protection are separate</h2><p>The earlier adaptive replay bought NVDA six times and MSFT seven times in 2023, yet its control lost 4.97% that year with 46.90% average exposure. Ninety-two ATR-stop sales realized −$869.96. This supports investigating repeated exits, cash and sizing even when leaders were shortlisted. It does not prove what a no-stop counterfactual would earn. An earlier MU April 2024 release setup subsequently lost 28.54% over 252 sessions with −57.82% stock-path drawdown. Failures and missed-opportunity questions are retained in <a href="failure_attribution.md">failure_attribution.md</a>.</p>')
    parts.append('<h2>Research integrity and next admissible experiment</h2><p>Data lookahead concerns information unavailable at the historical decision. Research overfitting concerns designing rules after seeing outcomes and calling those same outcomes independent evidence. Repairing the former does not repair the latter.</p><p>Proposed chronological plan: 2010–2018 training, 2019–2021 validation, 2022–2025 retrospective evaluation, followed by a genuinely unobserved period beginning after the full rule/data freeze. Training data and adaptive industry rules are not yet available; no fitted or frozen D/E is claimed. All previously viewed 2022–2025 years remain retrospective even after data repairs. Four calendar years cannot establish a reliable long-term success probability.</p><p>Each future signal requires immutable source lineage and availability timestamps strictly before the signal. Prices must come from the preceding completed session; orders execute later using raw marketable prices and explicit costs. Dividend receivables/cash, spinoff distributions and delisting consideration require actual economic capital accounting. Historical consensus is omitted until vintage data exists. One changed variable per experiment; no year-specific exceptions or threshold changes after test results without exploratory classification.</p>')
    parts.append('<h2>Evidence-based decision</h2><p><strong>Insufficient data.</strong> Growth/earnings/margin selection and winner retention are promising research candidates, but no sustainable annual return estimate is defensible. The +33% overlapping holding median is the strongest descriptive alternative in this evidence package, not a long-term return target. The gap to +80% is unresolved bearish/recovery-regime performance, exceptional-winner dependence, correct original control, complete PIT inputs and independently unseen testing.</p>')
    parts.append('<h2>Reproducibility and files</h2><p>'+str(verification['source_hashes_verified'])+' exact source snapshots match Git blob hashes and SHA-256; '+str(verification['archived_scenarios_indexed'])+' inherited continuous scenarios are indexed; 264 holding accounts are reaggregated. '+str(tests['tests'])+' auditor tests pass, including six deliberate accounting corruptions. These checks validate evidence and arithmetic only. The original 1,144-file ZIP is not present and was not reverified. No application, paper-trading, broker, workflow or deployment files were changed.</p><p><code>python research_5x/point_in_time_validation/validate_archive.py --strict</code> intentionally exits 2 for BLOCKED validation after generating the milestone. Source code here is an auditor/report generator, not a complete six-strategy simulator.</p><ul class="links">')
    parts.extend('<li><a href="'+esc(d)+'">'+esc(d)+'</a></li>' for d in documents)
    parts.append('</ul><p class="muted">Base archive commit: '+esc(config['base_commit'])+'. Earlier archives remain unchanged; this directory is added on a dedicated research branch.</p></main></html>')
    (ROOT / 'validation_report.html').write_text('\n'.join(parts))
    (ROOT / 'archived_winner_nav.svg').write_text(chart(read_csv('archived_winner_nav.csv')).replace('<svg viewBox=', '<svg xmlns="http://www.w3.org/2000/svg" viewBox='))
    print('Wrote self-contained evidence report and standalone archived NAV chart')

if __name__ == '__main__': main()
